'use client';

import React, { useState, useEffect } from 'react';
import { getContent, saveContent } from './actions';
import styles from './admin.module.css';

const AdminPage = () => {
    const [content, setContent] = useState<any>(null);
    const [saving, setSaving] = useState(false);
    const [activeTab, setActiveTab] = useState('home');
    const [isAuthenticated, setIsAuthenticated] = useState(false);
    const [usernameInput, setUsernameInput] = useState('');
    const [passwordInput, setPasswordInput] = useState('');
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const checkAuth = async () => {
            try {
                const response = await fetch('/api/login/check');
                if (response.ok) {
                    setIsAuthenticated(true);
                    const data = await getContent();
                    setContent(data);
                }
            } catch (error) {
                console.error('Auth check failed');
            } finally {
                setLoading(false);
            }
        };
        checkAuth();
    }, []);

    const handleLogin = async (e: React.FormEvent) => {
        e.preventDefault();
        try {
            const response = await fetch('/api/login', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ username: usernameInput, password: passwordInput })
            });

            if (response.ok) {
                setIsAuthenticated(true);
                const data = await getContent();
                setContent(data);
            } else {
                const err = await response.json();
                alert(err.error || 'Ошибка входа');
            }
        } catch (error) {
            alert('Ошибка сети или сервера');
        }
    };

    if (loading) return <div style={{ color: '#fff', padding: '100px', textAlign: 'center' }}>Загрузка...</div>;

    if (!isAuthenticated) {
        return (
            <div className={styles.loginContainer}>
                <form className={`${styles.loginCard} glass-card`} onSubmit={handleLogin}>
                    <h2>Вход в панель</h2>
                    <div className={styles.field}>
                        <label>Логин</label>
                        <input
                            type="text"
                            value={usernameInput}
                            onChange={(e) => setUsernameInput(e.target.value)}
                            placeholder="Логин"
                            required
                        />
                    </div>
                    <div className={styles.field}>
                        <label>Пароль</label>
                        <input
                            type="password"
                            value={passwordInput}
                            onChange={(e) => setPasswordInput(e.target.value)}
                            placeholder="Введите пароль..."
                            required
                        />
                    </div>
                    <button type="submit" className="primary-button primary-button--filled" style={{ width: '100%' }}>
                        Войти
                    </button>
                    <p style={{ fontSize: '12px', color: 'rgba(255,255,255,0.4)', textAlign: 'center', marginTop: '10px' }}>
                        Все данные зашифрованы по стандарту BCrypt
                    </p>
                </form>
            </div>
        );
    }

    const handleSave = async () => {
        setSaving(true);
        await saveContent(content);
        setSaving(false);
        alert('Данные сохранены!');
    };

    const tabs = [
        { id: 'home', label: 'Главная' },
        { id: 'pricing', label: 'Цены' },
        { id: 'tech', label: 'Технологии' },
        { id: 'portfolio', label: 'Кейсы' },
        { id: 'settings', label: 'Настройки' },
    ];

    return (
        <div className={styles.adminContainer}>
            <header className={styles.header}>
                <div>
                    <h1>Админ-панель PULSE 3D</h1>
                    <div className={styles.tabs}>
                        {tabs.map(tab => (
                            <button
                                key={tab.id}
                                className={`${styles.tab} ${activeTab === tab.id ? styles.activeTab : ''}`}
                                onClick={() => setActiveTab(tab.id)}
                            >
                                {tab.label}
                            </button>
                        ))}
                    </div>
                </div>
                <button
                    className="primary-button primary-button--filled"
                    onClick={handleSave}
                    disabled={saving}
                >
                    {saving ? 'Сохранение...' : 'Сохранить всё'}
                </button>
            </header>

            <div className={styles.content}>
                {activeTab === 'home' && (
                    <section className={styles.section}>
                        <h2>Главная страница</h2>
                        <div className={styles.field}>
                            <label>H1 Заголовок</label>
                            <input
                                value={content.home.heroTitle}
                                onChange={(e) => setContent({ ...content, home: { ...content.home, heroTitle: e.target.value } })}
                            />
                        </div>
                        <div className={styles.field}>
                            <label>Описание в Hero</label>
                            <textarea
                                value={content.home.heroDesc}
                                rows={3}
                                onChange={(e) => setContent({ ...content, home: { ...content.home, heroDesc: e.target.value } })}
                            />
                        </div>
                    </section>
                )}

                {activeTab === 'pricing' && (
                    <section className={styles.section}>
                        <h2>Цены (Тарифы)</h2>
                        {content.pricing.tariffs.map((tariff: any, idx: number) => (
                            <div key={idx} className={styles.itemBox}>
                                <h3>Тариф: {tariff.name}</h3>
                                <div className={styles.field}>
                                    <label>Цена</label>
                                    <input
                                        value={tariff.price}
                                        onChange={(e) => {
                                            const newTariffs = [...content.pricing.tariffs];
                                            newTariffs[idx].price = e.target.value;
                                            setContent({ ...content, pricing: { ...content.pricing, tariffs: newTariffs } });
                                        }}
                                    />
                                </div>
                                <div className={styles.field}>
                                    <label>Материалы</label>
                                    <input
                                        value={tariff.materials}
                                        onChange={(e) => {
                                            const newTariffs = [...content.pricing.tariffs];
                                            newTariffs[idx].materials = e.target.value;
                                            setContent({ ...content, pricing: { ...content.pricing, tariffs: newTariffs } });
                                        }}
                                    />
                                </div>
                            </div>
                        ))}
                    </section>
                )}

                {activeTab === 'tech' && (
                    <section className={styles.section}>
                        <h2>Оборудование</h2>
                        {content.tech.equipment.map((item: any, idx: number) => (
                            <div key={idx} className={styles.itemBox}>
                                <h3>{item.name}</h3>
                                <div className={styles.field}>
                                    <label>Описание</label>
                                    <textarea
                                        value={item.desc}
                                        rows={2}
                                        onChange={(e) => {
                                            const newEquip = [...content.tech.equipment];
                                            newEquip[idx].desc = e.target.value;
                                            setContent({ ...content, tech: { ...content.tech, equipment: newEquip } });
                                        }}
                                    />
                                </div>
                                <div className={styles.field}>
                                    <label>Применение</label>
                                    <input
                                        value={item.usage}
                                        onChange={(e) => {
                                            const newEquip = [...content.tech.equipment];
                                            newEquip[idx].usage = e.target.value;
                                            setContent({ ...content, tech: { ...content.tech, equipment: newEquip } });
                                        }}
                                    />
                                </div>
                            </div>
                        ))}
                    </section>
                )}

                {activeTab === 'portfolio' && (
                    <section className={styles.section}>
                        <h2>Портфолио (Кейсы)</h2>
                        {content.portfolio.works.map((work: any, idx: number) => (
                            <div key={idx} className={styles.itemBox}>
                                <h3>Кейс #{idx + 1}</h3>
                                <div className={styles.field}>
                                    <label>Название</label>
                                    <input
                                        value={work.title}
                                        onChange={(e) => {
                                            const newWorks = [...content.portfolio.works];
                                            newWorks[idx].title = e.target.value;
                                            setContent({ ...content, portfolio: { ...content.portfolio, works: newWorks } });
                                        }}
                                    />
                                </div>
                                <div className={styles.field}>
                                    <label>Материал</label>
                                    <input
                                        value={work.material}
                                        onChange={(e) => {
                                            const newWorks = [...content.portfolio.works];
                                            newWorks[idx].material = e.target.value;
                                            setContent({ ...content, portfolio: { ...content.portfolio, works: newWorks } });
                                        }}
                                    />
                                </div>
                            </div>
                        ))}
                    </section>
                )}

                {activeTab === 'settings' && (
                    <section className={styles.section}>
                        <h2>Настройки уведомлений</h2>
                        <div className={styles.field}>
                            <label>Telegram Bot Token</label>
                            <input
                                type="password"
                                value={content.settings.telegramToken}
                                onChange={(e) => setContent({ ...content, settings: { ...content.settings, telegramToken: e.target.value } })}
                            />
                        </div>
                        <div className={styles.field}>
                            <label>Telegram Chat ID</label>
                            <input
                                value={content.settings.telegramChatId}
                                onChange={(e) => setContent({ ...content, settings: { ...content.settings, telegramChatId: e.target.value } })}
                            />
                        </div>
                        <div className={styles.field}>
                            <label>Контактный телефон</label>
                            <input
                                value={content.settings.contactPhone}
                                onChange={(e) => setContent({ ...content, settings: { ...content.settings, contactPhone: e.target.value } })}
                            />
                        </div>
                        <div className={styles.field}>
                            <label>Email</label>
                            <input
                                value={content.settings.contactEmail}
                                onChange={(e) => setContent({ ...content, settings: { ...content.settings, contactEmail: e.target.value } })}
                            />
                        </div>
                    </section>
                )}
            </div>
        </div>
    );
};

export default AdminPage;
